package com.brasa.restaurant.controller;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.service.PublicService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/public/{slug}")public class PublicController{private final PublicService s;public PublicController(PublicService s){this.s=s;}@GetMapping public RestauranteResponse restaurant(@PathVariable String slug){return s.restaurantDto(slug);}@GetMapping("/categorias")public List<CategoriaDto>categories(@PathVariable String slug){return s.categories(slug);}@GetMapping("/produtos")public List<ProdutoDto>products(@PathVariable String slug){return s.products(slug);}@GetMapping("/mesas/{mesa}/pedidos")public List<PedidoResponse>orders(@PathVariable String slug,@PathVariable int mesa){return s.tableOrders(slug,mesa);}@GetMapping("/mesas/{mesa}/status")public MesaStatusResponse status(@PathVariable String slug,@PathVariable int mesa){return s.tableStatus(slug,mesa);}@PostMapping("/pedidos")@ResponseStatus(HttpStatus.CREATED)public PedidoResponse order(@PathVariable String slug,@Valid@RequestBody CriarPedidoRequest x){return s.createOrder(slug,x);}@PostMapping("/chamados")@ResponseStatus(HttpStatus.CREATED)public ChamadoResponse call(@PathVariable String slug,@Valid@RequestBody ChamadoRequest x){return s.call(slug,x);}}
